import glob, re
spec={"قلب":("طب القلب","القلب عضلة بحجم قبضة اليد، بيضخ حوالي 5 لتر دم في الدقيقة"),"عين":("طب العيون","العين فيها قرنية وعدسة وشبكية، والشبكية فيها خلايا حساسة للضوء"),"عيون":("طب العيون","العين فيها قرنية وعدسة وشبكية"),"عقل":("المخ والأعصاب","المخ فيه حوالي 86 مليار خلية عصبية بتتواصل بإشارات كهربائية"),"دماغ":("المخ والأعصاب","المخ فيه حوالي 86 مليار خلية عصبية"),"رئة":("طب الصدر","الرئة فيها حوالي 300 مليون حويصلة هوائية لتبادل الغازات"),"كبد":("طب الكبد","الكبد أكبر غدة، بينظف الدم وبيخزن الجليكوجين والفيتامينات"),"كلى":("طب الكلى","الكلى بتفلتر حوالي 180 لتر دم يوميا، وبتخرج الفضلات في البول"),"حمل":("طب النساء والتوليد","الحمل بيستمر حوالي 40 أسبوع، والجنين بيتكون من خلية واحدة")}
spec.update({"عظم":("طب العظام","العظم نسيج حي، فيه نخاع بيصنع خلايا الدم"),"جلد":("الجلدية","الجلد أكبر عضو، بيحمي الجسم وينظم الحرارة"),"أسنان":("طب الأسنان","السن فيه مينا وهي أقوى مادة في الجسم"),"معدة":("الجهاز الهضمي","المعدة بتفرز حمض وحمض البيبسين لهضم البروتين"),"دم":("طب الدم","الدم فيه كرات حمراء بتشيل الأكسجين وبيضاء للدفاع"),"أذن":("الأنف والأذن","الأذن فيها 3 عظيمات صغيرة بتنقل الصوت"),"سكر":("الغدد الصماء","السكر بيتظبط بهرمون الأنسولين من البنكرياس"),"مناعة":("المناعة","جهاز المناعة بيميز بين خلايا الجسم والميكروبات"),"عضلة":("العلاج الطبيعي","العضلة بتنقبض لما توصلها إشارة من العصب"),"طفل":("طب الأطفال","الطفل بينمو بسرعة وأهم حاجة التغذية والتطعيمات")})
for f in glob.glob("site/lessons/*_pages/page-*.html"):
 t=open(f,encoding="utf-8").read()
 lesson=f.split("_pages")[0]+".html"
 em="🧬"; title=""
 try:
  lt=open(lesson,encoding="utf-8").read()
  m=re.findall(r"[🫀🧠👁️🫁🦴🦷🩸👂👃✋🦶💪🤰👶🛡️🧬❤️🌿🍎💊🩺🫘]+",lt)
  if m: em=m[0]
  h=re.search(r"<h1>(.*?)</h1>",lt)
  if h: title=h.group(1)
 except: pass
 if not title:
  h=re.search(r"<h1>(.*?)</h1>",t)
  title=h.group(1) if h else "الدرس"
 sp,info="طب متخصص","هذا العضو يعمل بنظام دقيق، وأي خلل فيه يظهر في شكل أعراض واضحة"
 for k,v in spec.items():
  if k in title: sp,info=v; break
 i=int(re.search(r"page-(\d+)",f).group(1))
 cats=["التشريح الدقيق","الوظيفة الفسيولوجية","الأمراض الشائعة","التشخيص الطبي","العلاج والوقاية","التغذية العلاجية","الرياضة والتأهيل","الحالات الطارئة","أحدث الأبحاث","مراجعة طبية"]
 cat=cats[(i-1)//10]
 t=re.sub(r"<div class='illustration-box'.*?</div></div>","",t,flags=re.S)
 t=re.sub(r"<img[^>]+loremflickr[^>]+>","",t)
 box=f"<div class='illustration-box' style='background:#e3f2fd;border:2px solid #2196f3;border-radius:20px;padding:20px;text-align:center'><div style='font-size:80px'>{em}</div><div><b>رسم توضيحي: {title} - صفحة {i}</b></div><div style='background:white;padding:10px;margin-top:10px;text-align:right'><b>معلومة موثقة:</b> {info}</div></div>"
 body=f"<h1>{title}</h1><p style='color:#007bff'>🩺 التخصص: {sp}</p>"+box+f"<h2>📖 صفحة {i} / 100 - {cat}</h2><h3>1. شرح مراجع في {cat}</h3><p>في تخصص {sp}، {title} له دور أساسي. {info}. في قسم {cat} سنتعرف على التفاصيل التي يدرسها الطبيب، بعيدا عن الكلام العام.</p><h3>2. ماذا يحدث داخل الجسم؟</h3><p>عندما يعمل {title} بشكل سليم، الجسم كله يكون متوازن. وعندما يحدث التهاب أو نقص فيتامينات أو ضغط مستمر، يبدأ {title} في إرسال إشارات تعب. لذلك ملاحظة الأعراض بدري مهمة جدا.</p><h3>3. التشخيص والعلاج</h3><p>الطبيب في {sp} يعتمد على: الفحص السريري، تحليل الدم، والأشعة. العلاج يختلف حسب الحالة: دواء، نظام غذائي، علاج طبيعي، أو جراحة في الحالات المتقدمة. الوقاية أهم من العلاج: أكل صحي، نوم 7-8 ساعات، رياضة 30 دقيقة، والبعد عن التدخين.</p><h3>💡 معلومة مهمة</h3><p>اعمل فحص دوري كل 6 شهور، ولو حسيت بألم مستمر أو تعب غير طبيعي في {title}، روح للدكتور فورا، لا تأخذ دواء من نفسك.</p><h3>✍️ سؤال للمراجعة</h3><p>اذكر 3 أعراض تدل على مشكلة في {title}، و 3 خطوات للوقاية منه.</p><br><div style='display:flex;justify-content:space-between'><a href='page-{i-1}.html'>⬅ السابق</a><a href='../../{lesson.split('/')[-1]}'>🏠 القائمة</a><a href='page-{i+1}.html'>التالي ➡</a></div>"
 new=f"<html><head><meta charset='utf-8'><title>{title} - {i}</title></head><body style='font-family:sans-serif;padding:20px;max-width:700px;margin:auto'>{body}</body></html>"
 open(f,"w",encoding="utf-8").write(new)
print("150 FIXED + REVIEWED")
